function getLanguage() {
	const saved = localStorage.getItem("language")

	if (saved === "pt" || saved === "en") {
		return saved
	}

	return navigator.language.toLowerCase().startsWith("pt") ? "pt" : "en"
}

function setLanguage(language) {
	localStorage.setItem("language", language)
	updatePage()
}

function setIcon(element, server) {
	if (!element) {
		return
	}

	element.style.backgroundImage = ""
	element.textContent = server.short

	if (server.icon) {
		element.style.backgroundImage = `url("${server.icon}")`
		element.textContent = ""
	}
}

function setProfile() {
	const icon = document.getElementById("profileIcon")
	const name = document.getElementById("siteName")

	if (name) {
		name.textContent = settings.name
	}

	if (!icon) {
		return
	}

	icon.style.backgroundImage = ""
	icon.textContent = settings.name.charAt(0).toUpperCase()

	if (settings.profileimage) {
		icon.style.backgroundImage = `url("${settings.profileimage}")`
		icon.textContent = ""
	}
}

function createServerList(language) {
	const list = document.getElementById("serverList")

	if (!list) {
		return
	}

	list.innerHTML = ""

	servers.forEach(server => {
		const card = document.createElement("a")
		card.className = "serverCard"
		card.href = `server.html?id=${server.id}`

		const icon = document.createElement("div")
		icon.className = "serverIcon"
		setIcon(icon, server)

		const text = document.createElement("div")
		text.className = "serverText"

		const name = document.createElement("strong")
		name.textContent = server.name

		const description = document.createElement("span")
		description.textContent = server.description[language]

		const arrow = document.createElement("span")
		arrow.className = "arrow"
		arrow.textContent = "→"

		text.append(name, description)
		card.append(icon, text, arrow)
		list.appendChild(card)
	})
}

function loadServerPage(language) {
	const name = document.getElementById("serverName")

	if (!name) {
		return
	}

	const params = new URLSearchParams(window.location.search)
	const id = params.get("id")
	const server = servers.find(item => item.id === id) || servers[0]
	const icon = document.getElementById("serverIcon")
	const banner = document.getElementById("serverBanner")
	const description = document.getElementById("serverDescription")
	const joinbutton = document.getElementById("joinButton")
	const jointext = document.getElementById("joinText")
	const backbutton = document.getElementById("backButton")

	document.title = server.name
	name.textContent = server.name
	description.textContent = server.fulldescription[language]
	joinbutton.href = server.invite
	jointext.textContent = texts[language].join
	backbutton.textContent = texts[language].back

	if (banner) {
		if (server.banner) {
			banner.style.backgroundImage = `url("${server.banner}")`
			banner.classList.add("visible")
		} else {
			banner.style.backgroundImage = ""
			banner.classList.remove("visible")
		}
	}

	setIcon(icon, server)
}

function updateLanguageButtons(language) {
	const buttons = document.querySelectorAll("[data-language]")

	buttons.forEach(button => {
		button.classList.toggle("active", button.dataset.language === language)
	})
}

function updatePage() {
	const language = getLanguage()
	const description = document.getElementById("siteDescription")

	document.documentElement.lang = language === "pt" ? "pt-BR" : "en"

	if (description) {
		description.textContent = texts[language].description
	}

	setProfile()
	createServerList(language)
	loadServerPage(language)
	updateLanguageButtons(language)
}

document.querySelectorAll("[data-language]").forEach(button => {
	button.addEventListener("click", () => {
		setLanguage(button.dataset.language)
	})
})

updatePage()
